    # Accumulator rules for state counters (e.g., coins)
    # These tell the exporter how to parse items like "60 coins" -> add 60 to " coins" counter
    accumulator_rules: ClassVar[list] = [
        {"pattern": r"^(\d+) Qi Gems$", "extract_value": True, "target": "QI GEMS", "discriminator": None},
        {"pattern": r"^(\d+) Golden Walnuts$", "extract_value": True, "target": "GOLDEN WALNUTS", "discriminator": None},
    ]

    # Initial values for prog_items accumulators
    prog_items_init: ClassVar[dict] = {
        "QI GEMS": 0,
        "GOLDEN WALNUTS": 0,
        "Received Progression Item": 0,
        "Received Progression Percent": 0,
    }

    def generate_early(self) -> None:
        """Push starting items as precollected."""
        self._push_starting_items()

    def create_regions(self) -> None:
        """Create regions, locations, and connections."""
        create_regions(self.multiworld, self.player)

    def set_rules(self) -> None:
        """Set access rules."""
        set_rules(self)

    # Total progression items - set during create_items for Received Progression Percent tracking
    total_progression_items: int = 0

    def collect(self, state: "CollectionState", item: "Item") -> bool:
        """Collect item and track cumulative counters from accumulator rules."""
        import re
        change = super().collect(state, item)
        if change:
            # Track accumulator rules
            for rule in self.accumulator_rules:
                match = re.match(rule["pattern"], item.name)
                if match:
                    if rule["extract_value"]:
                        value = int(match.group(1))
                    else:
                        value = 1
                    state.prog_items[item.player][rule["target"]] += value
                    break

            # Track Received Progression Percent for progression items
            if item.classification == ItemClassification.progression:
                player_state = state.prog_items[self.player]
                received_progression_count = player_state["Received Progression Item"]
                received_progression_count += 1
                if self.total_progression_items:
                    player_state["Received Progression Percent"] = received_progression_count * 100 // self.total_progression_items
                player_state["Received Progression Item"] = received_progression_count

        return change

    def remove(self, state: "CollectionState", item: "Item") -> bool:
        """Remove item and update cumulative counters from accumulator rules."""
        import re
        change = super().remove(state, item)
        if change:
            # Track accumulator rules
            for rule in self.accumulator_rules:
                match = re.match(rule["pattern"], item.name)
                if match:
                    if rule["extract_value"]:
                        value = int(match.group(1))
                    else:
                        value = 1
                    state.prog_items[item.player][rule["target"]] -= value
                    break

            # Track Received Progression Percent for progression items
            if item.classification == ItemClassification.progression:
                player_state = state.prog_items[self.player]
                received_progression_count = player_state["Received Progression Item"]
                received_progression_count -= 1
                if self.total_progression_items:
                    player_state["Received Progression Percent"] = received_progression_count * 100 // self.total_progression_items
                player_state["Received Progression Item"] = received_progression_count

        return change

    def create_items(self) -> None:
        """Create randomized item pool."""
        # First, place any locked items
        self._place_locked_items()

        # Then create the random item pool
        item_pool = []

        for item_name, count in ITEMPOOL_COUNTS.items():
            # Skip event items
            if item_name not in item_table or item_table[item_name].id is None:
                continue

            item_data = item_table[item_name]
            for _ in range(count):
                item = StardewValleyWorldGenItem(
                    item_name,
                    item_data.classification,
                    item_data.id,
                    self.player
                )
                item_pool.append(item)

        self.multiworld.itempool += item_pool

        # Calculate total progression items for Received Progression Percent tracking
        # This counts progression items from the pool plus precollected items
        self.total_progression_items = sum(
            1 for item in item_pool
            if item.classification == ItemClassification.progression
        )
        # Add precollected progression items (starting items)
        for item_name, count in STARTING_ITEMS.items():
            if item_name in item_table and item_table[item_name].classification == ItemClassification.progression:
                self.total_progression_items += count

    def _place_locked_items(self) -> None:
        """Place items that must be in specific locations (locked placements)."""
        for location_name, item_name in LOCKED_PLACEMENTS.items():
            if item_name and item_name in item_table:
                location = self.multiworld.get_location(location_name, self.player)
                item_data = item_table[item_name]
                item = StardewValleyWorldGenItem(
                    item_name,
                    item_data.classification,
                    item_data.id,
                    self.player
                )
                location.place_locked_item(item)

    def _push_starting_items(self) -> None:
        """Push starting items as precollected (for state counters like coins)."""
        for item_name, count in STARTING_ITEMS.items():
            if item_name in item_table:
                for _ in range(count):
                    item = self.create_item(item_name)
                    self.multiworld.push_precollected(item)

    def generate_basic(self) -> None:
        """Place victory event item."""
        victory_location = self.multiworld.get_location("Complete Community Center", self.player)

        # Only place if not already filled (e.g., by _place_original_items)
        if victory_location.item is None:
            victory_item = StardewValleyWorldGenItem(
                "Victory",
                item_table["Victory"].classification,
                None,
                self.player
            )
            victory_location.place_locked_item(victory_item)

        # Set completion condition
        self.multiworld.completion_condition[self.player] = \
            lambda state: state.has("Victory", self.player)

    def create_item(self, name: str) -> Item:
        """Create an item by name."""
        data = item_table[name]
        return StardewValleyWorldGenItem(name, data.classification, data.id, self.player)


